    // ─────────── فصل ۱: آغاز سفر ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "The Journey Begins", titlePersian = "آغاز سفر",
        paragraphs = listOf(
            StoryParagraph("My name is Stevens, and I have been a butler for most of my life.", "نام من استیونز است و بیشتر عمرم را سرپیشخدمت بوده‌ام."),
            StoryParagraph("For thirty-five years, I served at Darlington Hall, one of the great houses of England.", "سی و پنج سال در تالار دارلینگتون خدمت کردم، یکی از خانه‌های بزرگ انگلستان."),
            StoryParagraph("Now, in the summer of 1956, I find myself on a journey through the English countryside.", "اکنون، در تابستان ۱۹۵۶، خود را در سفری از میان حومه انگلیس می‌یابم."),
            StoryParagraph("The house is no longer in the hands of the Darlington family.", "خانه دیگر در دست خانواده دارلینگتون نیست."),
